const raw = $input.first().json;
const d = raw.body || raw;
const missing = ['serviceType','startDate','endDate','serviceDuration'].filter(f => !d[f]);
if (missing.length) throw new Error('Missing required fields: ' + missing.join(', '));
return [{ json: d }];

const quoteRaw = $('Get Quote').first().json;
const quote = quoteRaw.body || quoteRaw;
const slots = $input.all().map(item => {
  const s = item.json.body || item.json;
  return {
    slot_number: s.slot_number,
    slot_start: s.slot_start,
    slot_end: s.slot_end,
    duration_minutes: s.duration_minutes,
    spoken_labels: s.spoken_labels
  };
});

return [{
  json: {
    quote_min: quote.quote_min,
    quote_max: quote.quote_max,
    manual_review: quote.manual_review || false,
    slots: slots
  }
}];
